import { computeEtag, hasMatchingEtag } from "../../utils/etag.js";
import { getRendererForProject } from "../../../shared/renderer-factory.js";
import { withSpan } from "../../../../observability/tracing/otlp-setup.js";
import { serverLogger } from "../../../../utils/index.js";
import { createHandlerDependencyPinningSource } from "../../utils/dependency-pinning-source.js";
import { applySnapshotResponseHeaders, readSnapshotHeader, resolveSnapshotForRequest, snapshotConflictResponse, snapshotStoreFailureResponse, stripSnapshotHeader, } from "../../utils/dependency-snapshot-protocol.js";
import { createApplicationRequestHeaders } from "../../../../security/http/application-request.js";
import { resolveSSRControlOutcome } from "../../../../rendering/ssr-outcome.js";
import { shouldHideRouteInProduction } from "../route-visibility-policy.js";
const DATA_ENDPOINT_PREFIX = "/_veryfront/data/";
export function handleDataEndpoint(req, pathname, ctx, createResponseBuilder, respond, getErrorMessage) {
    return withSpan("module.data.handle", async () => {
        try {
            // Anchored at the prefix rather than replacing its first occurrence,
            // so a slug that repeats the namespace keeps its own path.
            const rawSlug = pathname.slice(DATA_ENDPOINT_PREFIX.length).replace(/\.json$/, "");
            const encSlug = rawSlug === "index" ? "" : rawSlug;
            // Mirrors the dot-segment rejection the SSR handler applies before
            // rendering the same slug; this endpoint reaches renderPage too.
            if (shouldHideRouteInProduction(ctx, encSlug)) {
                serverLogger.warn("[data-endpoint] Dot path blocked in production", { pathname });
                const builder = createResponseBuilder(ctx)
                    .withCORS(req, ctx.securityConfig?.cors)
                    .withSecurity(ctx.securityConfig ?? undefined, req);
                applySnapshotResponseHeaders(builder.headers);
                return respond(builder.json({ error: "Page not found", status: 404 }, 404));
            }
            const requestUrl = new URL(req.url);
            const dependencySource = createHandlerDependencyPinningSource(ctx);
            const resolution = await resolveSnapshotForRequest(dependencySource, readSnapshotHeader(req.headers));
            if (resolution.kind === "conflict") {
                return respond(snapshotConflictResponse(createResponseBuilder(ctx), req, ctx.securityConfig));
            }
            const dependencySnapshot = resolution.snapshot;
            // The transport token must participate in framework caches without
            // leaking into application-visible request/query state.
            const applicationUrl = new URL(requestUrl);
            applicationUrl.pathname = encSlug ? `/${encSlug}` : "/";
            const applicationHeaders = createApplicationRequestHeaders(stripSnapshotHeader(req.headers), { denyHeaders: ctx.applicationIdentityHeaderNames });
            const applicationRequest = new Request(applicationUrl, {
                method: req.method,
                headers: applicationHeaders,
                signal: req.signal,
            });
            const renderer = await getRendererForProject(ctx);
            const result = await renderer.renderPage(encSlug, {
                request: applicationRequest,
                url: applicationUrl,
                dependencyPinningCacheKey: dependencySnapshot.cacheKey,
                dependencyPinningDependencies: dependencySnapshot.dependencies,
                dependencyPinningConfiguredVersions: dependencySnapshot.configuredVersions,
                dependencyPinningSource: dependencySource,
                applicationIdentity: ctx.applicationIdentity ?? null,
            });
            const data = {
                slug: encSlug,
                frontmatter: result.frontmatter,
                headings: result.headings,
                html: result.html,
                ...(dependencySnapshot.cacheKey === "off"
                    ? {}
                    : { dependencyPinningCacheKey: dependencySnapshot.cacheKey }),
            };
            const body = JSON.stringify(data);
            const etag = computeEtag(body);
            const builder = createResponseBuilder(ctx).withCORS(req, ctx.securityConfig?.cors);
            applySnapshotResponseHeaders(builder.headers, dependencySnapshot.cacheKey);
            if (hasMatchingEtag(req, etag)) {
                return respond(builder.notModified(etag));
            }
            return respond(builder
                .withSecurity(ctx.securityConfig ?? undefined, req)
                .withCache("no-cache")
                .withETag(etag)
                .json(data, 200));
        }
        catch (e) {
            const unavailable = snapshotStoreFailureResponse(e, createResponseBuilder(ctx), req, ctx.securityConfig);
            if (unavailable)
                return respond(unavailable);
            const errorMessage = getErrorMessage(e);
            const isNotFound = resolveSSRControlOutcome(e)?.kind === "not-found";
            const status = isNotFound ? 404 : 500;
            serverLogger.error("[data-endpoint] Failed to resolve data", {
                pathname,
                error: errorMessage,
                status,
            });
            const builder = createResponseBuilder(ctx)
                .withCORS(req, ctx.securityConfig?.cors)
                .withSecurity(ctx.securityConfig ?? undefined, req);
            applySnapshotResponseHeaders(builder.headers);
            return respond(builder.json({ error: isNotFound ? "Page not found" : "Internal server error", status }, status));
        }
    }, {
        "module.data.pathname": pathname,
        "module.data.projectSlug": ctx.projectSlug || "unknown",
    });
}
